from core.structured_output import STRING, STRINGS, object_schema

def array(items):
    return {'type': 'array', 'items': items}

def string_map():
    return {'type': 'object', 'additionalProperties': STRING}
NODE = object_schema({'id': STRING, 'type': {'type': 'string', 'enum': ['SUBJECT', 'ATTRIBUTE', 'ENTITY', 'EVENT', 'CONTEXT']}, 'value': STRING, 'source': {'type': 'string', 'enum': ['user', 'inferred'], 'description': 'Evidence origin for this node, not a graph endpoint.'}, 'aliases': STRINGS, 'long_term': {'type': 'boolean'}}, ['id', 'type', 'value', 'source'])
EDGE = object_schema({'id': {'type': 'string', 'description': 'New unique edge ID, distinct from node IDs.'}, 'source': {'type': 'string', 'description': 'Starting node ID from new_nodes or existing_graph.nodes; required on every edge.'}, 'target': {'type': 'string', 'description': 'Ending node ID from new_nodes or existing_graph.nodes; required on every edge, never a literal value.'}, 'type': {'type': 'string', 'description': 'Source-supported relationship label connecting source to target; not restricted to a fixed vocabulary.'}})
GRAPH_DELTA = object_schema({'new_nodes': array(NODE), 'new_edges': array(EDGE), 'node_updates': array(object_schema({'id': STRING, 'value': STRING, 'status': STRING, 'long_term': {'type': 'boolean'}}, ['id'])), 'edge_updates': array(object_schema({'id': STRING, 'status': STRING})), 'referenced_node_ids': STRINGS})
TASK = object_schema({'question': STRING, 'intent': STRING, 'output_goal': STRING, 'cloud_node_ids': {**STRINGS, 'description': 'Updated graph node IDs retained for locally rewritten real/shadow cases. Includes all critical_value_node_ids and public_concept_node_ids. Retains graph structure, not permission to disclose every raw private value; noncritical private values still require neutralization.'}, 'local_node_ids': {**STRINGS, 'description': 'Updated graph node IDs kept local rather than retained in the cloud case graph.'}, 'private_literals': STRINGS, 'public_concept_node_ids': {**STRINGS, 'description': 'A subset of cloud_node_ids containing only generic, non-identifying ENTITY categories, not named identities, private attributes, or values overlapping private literals.'}, 'critical_value_node_ids': {**STRINGS, 'description': 'A subset of cloud_node_ids containing atomic ATTRIBUTE, ENTITY or CONTEXT values necessary for remote reasoning because a faithful category, role, relation or placeholder cannot satisfy an explicit requirement or essential task constraint. Relevance and more tailored advice alone do not establish necessity. Each full value must match a private_literal and have a source-grounded critical_value_reasons entry. Copying or restoring a value in the final answer is not necessity.'}, 'critical_value_reasons': {**string_map(), 'description': 'For each critical node, identify the explicit task requirement that fails under a faithful abstraction and why local binding restoration cannot supply the missing cloud reasoning.'}})
NEUTRAL = object_schema({'question': STRING, 'intent': STRING, 'output_goal': STRING, 'neutralized_source_text': STRING, 'values': string_map(), 'identity_bindings': array(object_schema({'identity_id': STRING, 'neutral_label': STRING, 'source_forms': {'type': 'array', 'items': STRING, 'description': 'Exact source forms represented by this identity.'}, 'node_ids': {'type': 'array', 'items': STRING, 'description': 'Required on every binding: retained graph node IDs represented by this identity.'}}))})
SHADOW = object_schema({'values': string_map()})
CASES = object_schema({'cases': array(object_schema({'case_id': STRING, 'answer_text': STRING, 'missing_information': STRINGS}))})
